import 'express'

type UserRole = 'admin' | 'mitarbeiter' | 'kunde' | 'viewer'

interface IUser {
  id:             string
  email:          string
  firstName?:     string
  lastName?:      string
  role:           UserRole
  roles:          string[]
  permissions:    string[]
  organizationId?: string
  isActive:       boolean
  emailVerified:  boolean
  createdAt:      string
  updatedAt:      string
}

// Erweitert Express Request um req.user
declare module 'express' {
  interface Request {
    /** Eingeloggter User – gesetzt durch authMiddleware */
    user?: IUser
    /** User ID shortcut */
    userId?: string
  }
}
